h1 {
  position: relative;
  left: 2rem;     /* moved 2rem to the right; its original space stays reserved */
  top: 0.5rem;
}

.header {
  position: sticky;
  top: 0;
  z-index: 20;        /* above the page content that scrolls under it */
}

.dropdown {
  position: absolute;
  z-index: 10;        /* compared only with siblings in the same stacking context */
}

.card {
  transform: translateY(-4px);  /* creates a stacking context: a child z-index
                                   cannot escape above the header any more */
}
